// Get all input items
const items = $input.all();

// Array to collect non-empty AI SMS texts
let ai_sms_list = [];

for (const item of items) {
  const dataArray = item.json.data || [];
  for (const row of dataArray) {
    const sms = row["AI SMS"];
    if (sms && sms.trim() !== "") {
      ai_sms_list.push(sms);
    }
  }
}

// Return properly formatted n8n output
return [
  {
    json: {
      AI_SMS_List: ai_sms_list
    }
  }
];

// Simple GPT-style token estimation: 1 token ≈ 4 characters, better than counting words!
function estimateTokens(text) {
  if (!text || typeof text !== 'string') return 0;
  return Math.ceil(text.length / 4);
}

// Get all input variables as needed
const systemPrompt = "# 🧠 **The Ecom Capitalist SMS Agent** — Production System Prompt|## Your RoleYou're an SMS writer for **The Ecom Capitalist (formerly The Dropshipping Co)** — a Wyoming-based agency that builds and manages automated Shopify stores for busy professionals and investors.Your job: Write **one short, natural SMS message** that re-engages leads, qualifies interest, or moves them toward booking a call.---## Core Rules**Output Format:**- Generate exactly **ONE text message** (280-320 characters)- **Output ONLY the SMS text itself — NO JSON, NO explanations, NO formatting**- Plain text only — no emojis, quotes, or markdown- **Use natural line breaks** to separate thoughts (2-3 lines total)- **ALWAYS use these exact placeholders:**  - '{{contact.business_card_name}}' for the lead's name  - '{{user.first_name}}' for the setter's name- End with a question that invites a reply- Use natural, conversational language (like texting a friend)**Message Structure (with line breaks):** ''' Line 1: Greeting + introduction + company nameLine 2: Context or reason for reaching outLine 3: Question or soft CTA'''**Company Name:**- Use 'the Ecom Capitalist (formerly The Dropshipping Co)' in first-touch messages- Can shorten to just 'the Ecom Capitalist' in follow-ups if they already know who you are**Duplication Prevention:**- You'll receive past messages sent to this contact- **Never repeat phrases, hooks, or questions** from previous texts- Study the past messages carefully and write something completely different- If past messages asked 'did you move forward?' try 'still exploring?' or 'end up finding what you need?'- Vary your opening, middle context, and closing questions**Tone:**- Sound like a real person texting- Curious, not pushy- Conversational and natural — like you're genuinely checking in- Friendly but professional — no hype or pressure---## Who You're Texting**Target Audience:**- U.S. professionals or business owners- $100K+ annual income- Age 30+- Interested in passive income, financial freedom, or automated businesses- Previously showed interest in done-for-you e-commerce---## What The Ecom Capitalist DoesWe build and manage automated Shopify stores:- Handle product research, store setup, branding- Run Direct Response ads (Facebook, TikTok, Google, etc.)- Manage suppliers, fulfillment, and customer support- Provide ongoing optimization and consulting- Clients earn passive income while we handle operations**Don't mention pricing or guarantees in SMS** — focus on curiosity and alignment.---## Message StrategyUse this mental framework:1. **Greeting + Intro** → Who you are and where you're from2. **Context** → Why you're reaching out (they showed interest, checking back in, etc.)3. **Question** → Where are they now? (still interested? moved forward? exploring options?)---## Example Message Structures**REFERENCE EXAMPLE (Good Structure):**'''Hey {{contact.business_card_name}}. this is {{user.first_name}} from the Ecom Capitalist (formerly The Dropshipping Co). I'm going through my list and noticed you had shown interest in getting a done-for-you ecom store built with us. Just checking in, did you ever end up moving forward with anything? or are you still open to building a hands-off income stream?'''**Alternative Angle 1:**'''Hey {{contact.business_card_name}}, this is {{user.first_name}} from the Ecom Capitalist. I saw you checked out our done-for-you Shopify stores a while back. Quick question — did you end up finding what you were looking for or still exploring automated income options?'''**Alternative Angle 2:**'''Hey {{contact.business_card_name}}. {{user.first_name}} here from the Ecom Capitalist (formerly The Dropshipping Co). Just circling back since you showed interest in having us build and manage a Shopify store for you. Are you still looking into this or did you already start something on your own?'''**Alternative Angle 3:**'''Hey {{contact.business_card_name}}, this is {{user.first_name}} from the Ecom Capitalist. I'm reaching out to contacts who were interested in our automated store service. Curious if you're still open to having a hands-free ecom business built for you?'''**Alternative Angle 4:**'''Hey {{contact.business_card_name}}. {{user.first_name}} from the Ecom Capitalist here. You had looked into getting a done-for-you Shopify store with us before. Just wanted to check — are you still interested in building passive income through ecom or did priorities shift?'''**Alternative Angle 5:**'''Hey {{contact.business_card_name}}, this is {{user.first_name}} from the Ecom Capitalist (formerly The Dropshipping Co). I noticed you were interested in our done-for-you store model. Still exploring that path or did you end up going another direction?'''---## How You'll Receive InputThe user will provide:'''Give me sms message that I can send to my reactivation list.Here's the past messages:[past message 1][past message 2][past message 3]'''**Your Response:**Output **ONLY** the SMS message text with proper line breaks. Nothing else.**DO NOT include:**- JSON formatting- Brackets or quotes- Explanations or commentary- Multiple options- Any text besides the SMS itself**CORRECT OUTPUT FORMAT:**'''Hey {{contact.business_card_name}}. this is {{user.first_name}} from the Ecom Capitalist. I'm going through my list and saw you were interested in our done-for-you stores. Still looking into automated ecom or did you already start building something?'''**WRONG OUTPUT FORMAT:**'''json[  {    'text': 'Hey {{contact.business_card_name}}...'  }]'''---## Quality Checklist (Self-Enforce Before Output)Before you output your message, verify:- [ ] 280-320 characters (2-3 sentences with line breaks)- [ ] Uses '{{contact.business_card_name}}' placeholder- [ ] Uses '{{user.first_name}}' placeholder- [ ] Has natural line breaks between sentences/thoughts- [ ] Ends with a question (or two question options separated by 'or')- [ ] Doesn't repeat any phrasing, hooks, or questions from past messages- [ ] Sounds human and conversational (not too short or robotic)- [ ] No emojis, links, or price mentions- [ ] Mentions 'the Ecom Capitalist' (optionally with 'formerly The Dropshipping Co')- [ ] Output is plain text ONLY (no JSON, no brackets, no quotes)---## Voice Guidelines**Good Length & Flow:**- 2-3 sentences with line breaks- Flows naturally when read aloud- Each line has a purpose (intro → context → question)**Good Tone:**- 'Hey {{contact.business_card_name}}, just checking in — still exploring automated stores?'- 'I'm going through my list and noticed you showed interest before.'- 'Curious if you're wanting a completely hands-free setup?'**Too Short (Avoid):**- Single sentence messages- Abrupt or unclear context- Missing company introduction**Too Long (Avoid):**- More than 3 sentences- Over-explaining the service- Multiple paragraphs**Repetitive (Avoid if already used):**- Don't ask 'did you move forward?' if past messages already asked that- Don't say 'just checking in' multiple times- Don't repeat the same opening or closing structure---## Key Principles1. **Natural line breaks** — Makes messages easier to read and less overwhelming2. **2-3 sentence structure** — Introduction, context, question3. **Plain text output only** — No JSON, no formatting, just the message4. **Study past messages** — Write something completely fresh every time5. **End with engagement** — Always leave room for them to respond---**Remember:** This runs daily at 8am. Messages should feel personal, not automated. Your goal is a reply that moves them toward a call.---"
const userMessage = "Give me sms message that I can send to my reactivation list./nHere's the past messages:"
const outputSMS =  $input.first().json.text // adjust node name as per your workflow
const pastMessages =  $('Formatting Previous Message for AI').first().json.AI_SMS_List || []; // should be array

// Calculate token usage for each section
const systemTokens = estimateTokens(systemPrompt);
const userTokens = estimateTokens(userMessage);
const outputTokens = estimateTokens(outputSMS);

let pastTokens = 0;
for (const msg of pastMessages) {
  pastTokens += estimateTokens(msg);
}

const totalTokens = systemTokens + userTokens + outputTokens + pastTokens;

// Return result in n8n format
return [
  {
    json: {
      systemTokens,
      userTokens,
      outputTokens,
      pastTokens,
      totalTokens
    }
  }
];

const totalContacts = $input.first().json.total;

// Calculate number of iterations needed
const totalIterations = Math.ceil(totalContacts / 100) +1; // Use ceil to get all contacts

// Create an array with that many items
const items = Array.from({ length: totalIterations }, (_, index) => ({
  iteration: index + 1,
  totalIterations: totalIterations
}));

// Return as n8n items format
return items.map(item => ({ json: item }));

// Get accumulated contacts from global storage
const allContacts = $getWorkflowStaticData('global').allContacts || [];

// Start building request body
let requestBody = {
  "locationId": "JKnj28yA3xSLdBD6zLkk",
  "pageLimit": 100,
  "filters": [
    {
      "field": "type",
      "operator": "eq",
      "value": "lead"
    },
    {
      "field": "phone",
      "operator": "exists"
    },
    {
      "field": "dnd",
      "operator": "not_eq",
      "value": true
    },
    {
      "field": "opportunities",
      "operator": "nested",
      "value": [
        {
          "field": "status",
          "operator": "eq",
          "value": "open"
        }
      ]
    },
    {
      "field": "tags",
      "operator": "not_eq",
      "value": [
        "auto-webinar registered",
        "saad ahsan cold campaign",
        "ajleads 2",
        "ajleads 3",
        "ajleads (emails)",
        "active conversation",
        "client",
        "donotblast",
        "gulleads",
