        "team-member",
        "dq",
        "mobe_buyers1",
        "webinar registered",
        "tyler's own list",
        "webinar registered {{ '{' + '{' + 'custom_values.event_date_exact_day_1' + '}' + '}' }}"
      ]
    }
  ]
};

// If we have accumulated contacts, use the last one's searchAfter for pagination
// Otherwise, start with page 1
if (allContacts.length > 0) {
  const lastContact = allContacts[allContacts.length - 1];
  if (lastContact.searchAfter && Array.isArray(lastContact.searchAfter)) {
    Object.assign(requestBody, { searchAfter: lastContact.searchAfter });
  }
} else {
  Object.assign(requestBody, { page: 1 });
}

// Return the built request body
return {  requestBody };

// Get current batch of contacts from HTTP response
const currentContacts = $input.first().json.contacts || [];

// Extract only what we need (contact_id and first_name)
const extractedContacts = currentContacts.map(contact => ({
  contact_id: contact.id,
  first_name: contact.firstName || contact.firstNameLowerCase || null,
  searchAfter: contact.searchAfter
}));

// Get accumulated minimal contact data from workflow static storage
const allContacts = $getWorkflowStaticData('global').allContacts || [];

// Merge and deduplicate in one step
const mergedContacts = [...allContacts, ...extractedContacts];
const uniqueContacts = Array.from(
  new Map(mergedContacts.map(contact => [contact.contact_id, contact])).values()
);

// Save deduplicated contacts back to workflow static data
$getWorkflowStaticData('global').allContacts = uniqueContacts;

// Return current batch info + loop control
return {
  currentBatch: extractedContacts.length,
  totalAccumulated: uniqueContacts.length,
  duplicatesRemoved: mergedContacts.length - uniqueContacts.length,
  shouldContinue: currentContacts.length === 100,
  contacts: currentContacts  // pass full contacts to next node for searchAfter
};

// Retrieve all accumulated contacts (only ID and first name)
const allContacts = $getWorkflowStaticData('global').allContacts || [];

// Remove duplicates based on contact_id
const uniqueContacts = Array.from(
  new Map(allContacts.map(contact => [contact.contact_id, contact])).values()
);

// Clear the static data for next workflow run
$getWorkflowStaticData('global').allContacts = [];

// Return summary and data
return [{
  json: {
    total_contacts: uniqueContacts.length,
    original_count: allContacts.length,
    duplicates_removed: allContacts.length - uniqueContacts.length,
    contacts: uniqueContacts
  }
}];

const contactId = $input.first().json.contact_id;
const contactName = $input.first().json.first_name;
const messages = $('Basic LLM Chain').first().json.text;

// More flexible regex that handles various formats
const version1Match = messages.match(/Version 1:?\s*([\s\S]*?)(?=Version 2:|$)/);
const version2Match = messages.match(/Version 2:?\s*([\s\S]*?)$/);

const version1 = version1Match ? version1Match[1].trim() : '';
const version2 = version2Match ? version2Match[1].trim() : '';

// Select version based on contactName existence
let selectedMessage = contactName && version1 ? version1 : version2;

// Ensure we have a message to work with
if (!selectedMessage) {
  throw new Error('No valid message version found');
}

// Replace contact name placeholder if contactName exists
if (contactName) {
  selectedMessage = selectedMessage.replace(/\{\{contact\.firstName\}\}/g, contactName);
}

// Replace user first name
selectedMessage = selectedMessage.replace(/\{\{user\.first_name\}\}/g, 'Tyler');

return {
  contactId,
  contactName: contactName || null,
  messages: selectedMessage.trim()
};
